---
import '../styles/global.css';
import {site,menuGroups} from '../config/site';
import buildRevision from '../data/build-revision.json';
import products from '../data/products.json';
import provenance from '../data/social-image-provenance.json';
import {productSocialImage} from '../lib/social-image.mjs';
const {title,description,canonicalPath='/',noindex=false,includeSchema=true,orderUrl=site.orderUrl,socialProduct=products[0]}=Astro.props;
const canonical=canonicalPath===false ? '' : new URL(canonicalPath,site.domain).toString();
const socialImage=canonical ? productSocialImage(socialProduct,provenance,site.domain,site.brand) : null;
const indexable=site.indexable && !noindex;
const robots=site.indexable && canonical ? (noindex ? 'noindex,follow' : 'index,follow') : 'noindex,nofollow,noarchive';
const revision=buildRevision.revision || 'local';
---
<!doctype html><html lang="ko"><head>
<meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>{title}</title><meta name="description" content={description}/>
<meta name="robots" content={robots}/>
{indexable && <meta name="naver-site-verification" content={site.naverVerification}/>}
<meta name="site-factory-revision" content={revision}/>{canonical && <link rel="canonical" href={canonical}/>}
{canonical && <><meta property="og:type" content="website"/><meta property="og:title" content={title}/><meta property="og:description" content={description}/><meta property="og:url" content={canonical}/><meta property="og:locale" content="ko_KR"/></>}
{socialImage && <><meta property="og:image" content={socialImage.url}/><meta property="og:image:secure_url" content={socialImage.url}/><meta property="og:image:alt" content={socialImage.alt}/><meta property="og:image:type" content={socialImage.type}/><meta property="og:image:width" content={socialImage.width}/><meta property="og:image:height" content={socialImage.height}/><meta name="twitter:image" content={socialImage.url}/><meta name="twitter:image:alt" content={socialImage.alt}/></>}
<meta name="twitter:card" content="summary"/><meta name="twitter:title" content={title}/><meta name="twitter:description" content={description}/>
<meta name="theme-color" content="#3a214f"/>
{includeSchema && <script type="application/ld+json" set:html={JSON.stringify({'@context':'https://schema.org','@type':'Florist',name:site.brand,url:site.domain,telephone:site.phone,areaServed:site.region}).replace(/</g, String.fromCharCode(92) + 'u003c')}></script>}
</head><body>
<a class="skip-link" href="#main-content">본문 바로가기</a>
<header class="site-header"><div class="header-inner"><a class="brand" href="/"><span class="brand-icon">✿</span><span><b>{site.brand}</b><small>{site.region} 꽃배달</small></span></a>
<nav aria-label="주요 메뉴">{menuGroups.map(g=><a href={g.url}>{g.label}</a>)}</nav><a class="phone" href={site.phoneHref}>☎ {site.phone}</a></div></header>
<main id="main-content"><slot/></main>
<footer><div><strong>{site.brand} {site.region}</strong><span>{site.orderHours}</span><a href={site.phoneHref}>{site.phone}</a><a href={orderUrl}>온라인 주문</a></div></footer>
<div class="mobile-bar"><a href={site.phoneHref}>전화주문</a><a href={orderUrl}>온라인 주문</a></div>
</body></html>

